solution:
def rotate(items, k):
    if not items:
        return []
    k = k % len(items)
    return items[len(items) - k:] + items[:len(items) - k]

alt:
def rotate(items, k):
    items = list(items)
    if not items:
        return items
    for _ in range(k % len(items)):
        items.insert(0, items.pop())
    return items
